package org.sleepwell.app;
import android.content.Context;import android.net.Uri;import android.os.*;import java.lang.ref.WeakReference;import java.time.ZoneId;import java.util.concurrent.*;
/** Retained reviewed file; no URI grant is made by this worker. */
final class SleepSummaryJob {
 enum Phase{PREPARING,READY,VERIFYING,VERIFIED,ERROR}
 static final class State{final Phase phase;final int days;final SleepSummaryFiles.Snapshot snapshot;final Uri uri;final String message;State(Phase phase,int days,SleepSummaryFiles.Snapshot snapshot,Uri uri,String message){this.phase=phase;this.days=days;this.snapshot=snapshot;this.uri=uri;this.message=message;}boolean busy(){return phase==Phase.PREPARING||phase==Phase.VERIFYING;}}
 interface Observer{void changed(State state);}private final Context app;private final Records.Factory records;private final ExecutorService worker=Executors.newSingleThreadExecutor();private final Handler main=new Handler(Looper.getMainLooper());private WeakReference<Observer> observer=new WeakReference<>(null);private volatile boolean closed;private volatile int generation;private volatile long historyEpoch;private State state;private boolean historyInvalidated;private SleepSummaryFiles.Snapshot owned;
 SleepSummaryJob(Context context,int days,boolean restarted){app=context.getApplicationContext();records=Records.factory;prepare(days,restarted?"The earlier request was interrupted. Review this new snapshot before sharing.":"");}
 private boolean active(int ticket,long epoch){return !closed&&generation==ticket&&historyEpoch==epoch&&SleepSummaryFiles.current(epoch);}
 State state(){checkHistory();return state;}void observe(Observer value){observer=new WeakReference<>(value);checkHistory();value.changed(state);}void detach(Observer value){if(observer.get()==value)observer.clear();}
 private void publish(State value){if(closed)return;if(!SleepSummaryFiles.current(historyEpoch)){invalidateHistory();return;}state=value;Observer target=observer.get();if(target!=null)target.changed(value);}
 void checkHistory(){if(!closed&&!historyInvalidated&&!SleepSummaryFiles.current(historyEpoch))invalidateHistory();}
 private void invalidateHistory(){if(closed||historyInvalidated)return;historyInvalidated=true;generation++;state=new State(Phase.ERROR,state==null?7:state.days,null,null,"Sleep history changed. Prepare a new summary before sharing.");worker.execute(()->{if(owned!=null&&!SleepSummaryFiles.current(owned.epoch)){owned.discard();owned=null;}});Observer target=observer.get();if(target!=null)target.changed(state);}
 void prepare(int days){checkHistory();if(!closed&&!state.busy())prepare(days,"");}
 private void prepare(int days,String message){int selected=days==30?30:7;int ticket=++generation;long epoch=SleepSummaryFiles.epoch();historyEpoch=epoch;historyInvalidated=false;ZoneId zone=ZoneId.systemDefault();long now=System.currentTimeMillis();publish(new State(Phase.PREPARING,selected,null,null,"Preparing a private summary…"));worker.execute(()->{try{if(owned!=null){owned.discard();owned=null;}if(!active(ticket,epoch))throw new IllegalStateException("Sleep history changed. Prepare a new summary.");SleepSummary.Data data;try(Store store=records.open(app)){data=SleepSummary.read(store,selected,now,zone,()->active(ticket,epoch));}owned=SleepSummaryFiles.stage(app,data,epoch,()->active(ticket,epoch));SleepSummaryFiles.Snapshot snapshot=owned;main.post(()->{if(active(ticket,epoch))publish(new State(Phase.READY,selected,snapshot,null,data.rows.isEmpty()?"No closed periods in this date range. Nothing will be shared.":message));else checkHistory();});}catch(Exception failure){String error=notice(failure);main.post(()->{if(active(ticket,epoch))publish(new State(Phase.ERROR,selected,null,null,error));else checkHistory();});}});}
 private static String notice(Exception failure){if(failure instanceof IllegalStateException||failure instanceof IllegalArgumentException){String text=failure.getMessage();if(text!=null&&text.length()<240)return text;}return "The summary could not be prepared or verified. Nothing was shared. Choose the period again.";}
 void verifyShare(){checkHistory();State before=state;if(closed||before.phase!=Phase.READY||before.snapshot==null||before.snapshot.data.rows.isEmpty())return;int ticket=++generation;long epoch=historyEpoch;if(before.snapshot.epoch!=epoch||!active(ticket,epoch)){checkHistory();return;}publish(new State(Phase.VERIFYING,before.days,before.snapshot,null,"Verifying the exact reviewed file…"));worker.execute(()->{try{before.snapshot.verify(()->active(ticket,epoch));Uri uri=before.snapshot.uri(app);main.post(()->{if(active(ticket,epoch))publish(new State(Phase.VERIFIED,before.days,before.snapshot,uri,""));else checkHistory();});}catch(Exception failure){String error=notice(failure);main.post(()->{if(active(ticket,epoch))publish(new State(Phase.ERROR,before.days,before.snapshot,null,error));else checkHistory();});}});}
 void revokeShare(){checkHistory();if(closed||state.phase!=Phase.VERIFYING&&state.phase!=Phase.VERIFIED)return;generation++;publish(new State(Phase.READY,state.days,state.snapshot,null,"Share paused when this screen lost focus. Tap Share summary again when ready."));}
 void shared(){checkHistory();if(closed||state.phase!=Phase.VERIFIED||state.snapshot==null||state.snapshot.epoch!=historyEpoch)throw new IllegalStateException("No current verified summary.");SleepSummaryFiles.markShared(state.snapshot);}
 void close(){if(closed)return;closed=true;generation++;observer.clear();worker.execute(()->{if(owned!=null){owned.discard();owned=null;}});worker.shutdown();}
}
